def script(itens=ITENS):
    return """(()=>{const B=%s;const go=()=>{if(!document.head)return;let s=document.getElementById('lfBase');if(!s){s=document.createElement('style');s.id='lfBase';s.textContent=B.map(x=>x.css||'').join('\\n')}if(s!==document.head.lastElementChild)document.head.appendChild(s);B.forEach(x=>{if(x.js)try{(0,eval)('('+x.js+')')()}catch(e){}})};let t;new MutationObserver(()=>{clearTimeout(t);t=setTimeout(go,60)}).observe(document,{childList:true,subtree:true});document.addEventListener('DOMContentLoaded',go)})()"""%json.dumps(itens)
